using UnityEngine;
using Zombera.World.CityPipeline.WorldBuilder;
using Zombera.World.Roads;

public static class SceneHydroProbe
{
    public static string Run()
    {
        var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
        var sb = new System.Text.StringBuilder();
        sb.Append("scene=").Append(scene.name).Append(" dirty=").Append(scene.isDirty);
        var builder = Object.FindFirstObjectByType<CityPrefabRoadNetworkBuilder>(FindObjectsInactive.Include);
        sb.Append(" builder=").Append(builder != null);
        var service = Object.FindFirstObjectByType<WorldBuilderService>(FindObjectsInactive.Include);
        sb.Append(" service=").Append(service != null);
        if (service != null)
        {
            var a = service.Artifacts;
            sb.Append(" artifacts=").Append(a != null);
            if (a != null)
            {
                sb.Append(" landforms=").Append(a.Landforms != null);
                sb.Append(" hydro=").Append(a.Hydrology != null);
                sb.Append(" biomes=").Append(a.Biomes != null);
                if (a.Landforms != null)
                    sb.Append(" lfWH=").Append(a.Landforms.WorldHeights != null ? a.Landforms.WorldHeights.Length : 0)
                      .Append(" w=").Append(a.Landforms.Width).Append(" h=").Append(a.Landforms.Height);
                if (a.Hydrology?.Rivers != null)
                    sb.Append(" rivers=").Append(a.Hydrology.Rivers.Length);
            }
            var catalog = service.TileCatalog;
            sb.Append(" catalog=").Append(catalog != null);
            if (catalog != null)
            {
                var ok = catalog.TryGetWorldBoundsXZ(out var b, requireAllocatedTerrain: true);
                sb.Append(" terrainBounds=").Append(ok);
                if (ok) sb.Append(" bounds=").Append(b);
            }
        }
        var terrains = Object.FindObjectsByType<Terrain>(FindObjectsSortMode.None);
        sb.Append(" terrainCount=").Append(terrains != null ? terrains.Length : 0);
        return sb.ToString();
    }
}
